import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, vec4, texture, mix, smoothstep, fract, sin, dot, time, color, mul, add, sub } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, PlaneGeometry, Mesh, Vector2 } = THREE;

  const root = new Group();
  root.userData.handlers = {};
  root.userData.timelines = [];

  const specColors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // Preserve 512:320 atlas aspect ratio (1.6:1); card width 2.4 scene units
  const cardWidth = 2.4;
  const cardHeight = cardWidth * (320 / 512);
  const geometry = new PlaneGeometry(cardWidth, cardHeight);

  const material = new MeshBasicNodeMaterial({ transparent: true });

  const texPromise = ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    tex.colorSpace = THREE.SRGBColorSpace;
    tex.minFilter = THREE.LinearFilter;
    tex.magFilter = THREE.LinearFilter;

    const texColor = texture(tex, uv());
    const uvy = uv().y;

    // Engineered vertical gradient: surface at bottom, ink at top
    const grad = mix(
      color(specColors.surface),
      color(specColors.ink),
      smoothstep(0.0, 1.0, uvy)
    );

    // Subtle gradient overlay on top of card image
    const base = mix(texColor.rgb, grad, 0.12);

    // Animated subtle film grain
    const seed = add(dot(uv(), vec2(12.9898, 78.233)), mul(time, 0.05));
    const grain = fract(mul(sin(seed), 43758.5453));
    const grainAmt = 0.035;
    const grainShift = sub(mul(grain, grainAmt), mul(grainAmt, 0.5));
    const grained = add(base, grainShift);

    // Vignette/edge falloff to keep focus inward
    const vignette = smoothstep(1.0, 0.35, add(mul(Math.abs(uv().x - 0.5), 1.4), mul(Math.abs(uv().y - 0.5), 1.4)));
    const vignetted = mix(grained, mul(grained, 0.85), sub(1.0, vignette));

    material.colorNode = vec4(vignetted, texColor.a);
    material.needsUpdate = true;
  }).catch((err) => {
    // Graceful fallback: solid ink surface with gradient
    const grad = mix(color(specColors.surface), color(specColors.ink), smoothstep(0.0, 1.0, uv().y));
    material.colorNode = vec4(grad, 1.0);
    material.needsUpdate = true;
    console.warn('Feature card texture failed:', err);
  });

  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Apply cinematic primitives if any are declared
  const primitives = config.cinematicPrimitives ?? [];
  for (const p of primitives) {
    if (ctx.primitives[p.name]) {
      const result = ctx.primitives[p.name](root, p.params ?? {});
      if (result?.timeline) root.userData.timelines.push(result.timeline);
    }
  }

  root.userData.cleanup = () => {
    root.userData.timelines.forEach((tl) => { if (tl && typeof tl.kill === 'function') tl.kill(); });
    root.userData.timelines = [];
    geometry.dispose();
    material.dispose();
  };

  return root;
}
